---entire_api_old_natsdial---
// Package natsdial centralises NATS client connection setup. Auth is mTLS
// via the org-wide ENTIRE_INTERNAL_TLS_{CERT,KEY,CA}_FILE env vars.
//
// Cert rotation: the *tls.Config installs a GetClientCertificate callback
// that re-reads cert+key from disk on every TLS handshake. cert-manager
// rotates the per-app Secret every 5 days (48h renewBefore on a 7d cert);
// kubelet propagates the new files within ~60s; the next NATS reconnect
// picks up the new cert without a process restart.
//
// Lifted verbatim from entirehq/mirror-pipeline/internal/natsdial — keep
// these in sync until extracted into a shared library.
package natsdial

import (
	"crypto/tls"
	"crypto/x509"
	"errors"
	"fmt"
	"os"

	"github.com/nats-io/nats.go"
)

// Dial reads ENTIRE_INTERNAL_TLS_{CERT,KEY,CA}_FILE from the environment,
// builds a rotation-aware *tls.Config, and opens an mTLS NATS connection.
// Extra opts (e.g. nats.Name, ReconnectHandler) are appended to the
// option list so callers control their own connection naming and lifecycle.
func Dial(natsURL string, opts ...nats.Option) (*nats.Conn, error) {
	if natsURL == "" {
		return nil, errors.New("natsdial: natsURL is empty")
	}
	tlsConfig, err := configFromEnv()
	if err != nil {
		return nil, err
	}
	dialOpts := append([]nats.Option{
		nats.Secure(tlsConfig),
		// Long-lived services must outlive arbitrary NATS outages. The
		// client default gives up after 60 reconnect attempts (~2 min at
		// the default 2s wait) and permanently CLOSES the connection — the
		// pod then looks alive while every NATS operation fails until a
		// restart. Reconnect forever; callers can still override via opts.
		nats.MaxReconnects(-1),
	}, opts...)
	return nats.Connect(natsURL, dialOpts...)
}

func configFromEnv() (*tls.Config, error) {
	certFile := os.Getenv("ENTIRE_INTERNAL_TLS_CERT_FILE")
	keyFile := os.Getenv("ENTIRE_INTERNAL_TLS_KEY_FILE")
	caFile := os.Getenv("ENTIRE_INTERNAL_TLS_CA_FILE")
	if certFile == "" || keyFile == "" || caFile == "" {
		return nil, errors.New("natsdial: ENTIRE_INTERNAL_TLS_{CERT,KEY,CA}_FILE all required")
	}
	return buildTLSConfig(certFile, keyFile, caFile)
}

func buildTLSConfig(certFile, keyFile, caFile string) (*tls.Config, error) {
	if _, err := tls.LoadX509KeyPair(certFile, keyFile); err != nil {
		return nil, fmt.Errorf("natsdial: load tls keypair: %w", err)
	}
	caBytes, err := os.ReadFile(caFile)
	if err != nil {
		return nil, fmt.Errorf("natsdial: read ca: %w", err)
	}
	caPool := x509.NewCertPool()
	if !caPool.AppendCertsFromPEM(caBytes) {
		return nil, errors.New("natsdial: ca PEM: no certs parsed")
	}
	return &tls.Config{
		GetClientCertificate: func(_ *tls.CertificateRequestInfo) (*tls.Certificate, error) {
			cert, err := tls.LoadX509KeyPair(certFile, keyFile)
			if err != nil {
				return nil, err
			}
			return &cert, nil
		},
		RootCAs:    caPool,
		MinVersion: tls.VersionTLS13,
	}, nil
}

---entire_api_old_jsconsumer---
// Package jsconsumer factors the durable JetStream pull-consumer scaffold shared by
// the service's decode-and-dispatch lifecycle consumers (repolifecycle,
// settingsconsumer, mirrorlifecycle). Each of those hand-rolled the same lifecycle:
// jetstream.New → CreateOrUpdateConsumer (durable, explicit ack, 30s ack-wait,
// bounded MaxDeliver, filter subject) → Consume → stop on context cancel; and the
// same per-message prologue: open a consumer span (re-parented across the NATS hop),
// decode the payload, and Term on a decode error.
//
// This package owns exactly that scaffold and nothing else. Each consumer keeps its
// OWN event type, business dispatch (op switch, seed/apply/push), metrics, and log
// lines — Start takes the consumer's message callback, and Process invokes the
// consumer's handle with the decoded event and the live span.
package jsconsumer

import (
	"context"
	"fmt"
	"log/slog"
	"time"

	"github.com/nats-io/nats.go"
	"github.com/nats-io/nats.go/jetstream"
	"go.opentelemetry.io/otel/codes"
	"go.opentelemetry.io/otel/trace"

	"github.com/entirehq/entire-api/internal/otelnats"
	"github.com/entirehq/entire-api/internal/otelsetup"
)

const (
	// ackWait is how long JetStream waits for an ack before redelivery — shared by
	// every consumer here (30s: comfortably longer than a Core round-trip + a DB
	// upsert, short enough that a stuck message redelivers promptly).
	ackWait = 30 * time.Second
	// defaultMaxDeliver caps redelivery before JetStream terms a message when the
	// caller leaves Config.MaxDeliver zero — the posture the migrated consumers share.
	defaultMaxDeliver = 8
)

// Config describes the durable consumer to create and how to trace/log it. The
// filter is given as either FilterSubject (single) or FilterSubjects (multi),
// mirroring jetstream.ConsumerConfig, so a migrated consumer preserves its existing
// on-server filter form exactly.
type Config struct {
	Stream         string   // JetStream stream to bind (must already exist)
	Durable        string   // durable consumer name, stable across restarts
	FilterSubject  string   // set this OR FilterSubjects
	FilterSubjects []string // set this OR FilterSubject
	MaxDeliver     int      // 0 → defaultMaxDeliver
	SpanName       string   // per-message consumer span name (e.g. "repolifecycle.consume")
	Name           string   // short package name, used in the decode-error log prefix
}

// Runner is a live consume loop. Stop halts it and is idempotent.
type Runner struct{ cc jetstream.ConsumeContext }

// Stop halts the consume loop. Safe on a nil Runner and safe to call twice.
func (r *Runner) Stop() {
	if r != nil && r.cc != nil {
		r.cc.Stop()
		r.cc = nil
	}
}

// Start creates/updates the durable consumer on nc and begins delivering messages to
// onMsg, returning a Runner that Stops when ctx is cancelled. The stream must already
// exist (provisioned declaratively in fleet); callers gate Start behind their per-cell
// opt-in so a cell without the stream doesn't error at CreateOrUpdateConsumer.
func Start(ctx context.Context, nc *nats.Conn, cfg Config, onMsg func(jetstream.Msg)) (*Runner, error) {
	if nc == nil {
		return nil, fmt.Errorf("jsconsumer(%s): nil nats conn", cfg.Name)
	}
	js, err := jetstream.New(nc)
	if err != nil {
		return nil, fmt.Errorf("jsconsumer(%s): jetstream.New: %w", cfg.Name, err)
	}
	maxDeliver := cfg.MaxDeliver
	if maxDeliver == 0 {
		maxDeliver = defaultMaxDeliver
	}
	cons, err := js.CreateOrUpdateConsumer(ctx, cfg.Stream, jetstream.ConsumerConfig{
		Durable:        cfg.Durable,
		AckPolicy:      jetstream.AckExplicitPolicy,
		AckWait:        ackWait,
		MaxDeliver:     maxDeliver,
		FilterSubject:  cfg.FilterSubject,
		FilterSubjects: cfg.FilterSubjects,
	})
	if err != nil {
		return nil, fmt.Errorf("jsconsumer(%s): create consumer %s/%s: %w", cfg.Name, cfg.Stream, cfg.Durable, err)
	}
	cc, err := cons.Consume(onMsg)
	if err != nil {
		return nil, fmt.Errorf("jsconsumer(%s): consume %s: %w", cfg.Name, cfg.Stream, err)
	}
	r := &Runner{cc: cc}
	go func() {
		<-ctx.Done()
		r.Stop()
	}()
	return r, nil
}

// Process runs the per-message prologue shared by every consumer: open the consumer
// span (re-parented to the producer across the NATS hop), decode the payload, and on
// a decode error record it, log "<Name>: decode <Stream>; term", invoke onUndecodable
// (so the caller bumps its own drop metric with its own attributes), and Term the
// message — a poison payload won't decode on redelivery. On success it invokes handle
// with the span-enriched context, the live span (for RecordError/SetStatus on the
// business error paths), the message, and the decoded event.
//
// Callers wire Process as the func they pass to Start AND the entry point their tests
// drive, so the decode-or-term path is exercised the same way in production and tests.
func Process[E any](
	ctx context.Context,
	msg jetstream.Msg,
	cfg Config,
	decode func([]byte) (E, error),
	handle func(ctx context.Context, span trace.Span, msg jetstream.Msg, ev E),
	onUndecodable func(ctx context.Context),
) {
	ctx, span := otelnats.StartConsumerSpan(ctx, otelsetup.Tracer(), msg, cfg.SpanName)
	defer span.End()

	ev, err := decode(msg.Data())
	if err != nil {
		span.RecordError(err)
		span.SetStatus(codes.Error, "decode")
		slog.WarnContext(ctx, cfg.Name+": decode "+cfg.Stream+"; term",
			slog.Any("error", err), slog.String("subject", msg.Subject()))
		if onUndecodable != nil {
			onUndecodable(ctx)
		}
		_ = msg.Term()
		return
	}
	handle(ctx, span, msg, ev)
}

---entire_api_old_otelnats---
// Package otelnats propagates W3C trace context through NATS message headers
// so a consumer span parents to the remote producer span — joining the ingest,
// forwarder, and index-job hops into one end-to-end trace. Ported from
// mirror-pipeline/pkg/otelnats.
package otelnats

import (
	"context"

	"github.com/nats-io/nats.go"
	"go.opentelemetry.io/otel"
	"go.opentelemetry.io/otel/attribute"
	"go.opentelemetry.io/otel/propagation"
	"go.opentelemetry.io/otel/trace"
)

// HeaderCarrier adapts nats.Header to propagation.TextMapCarrier so the
// configured propagator can inject/extract traceparent and baggage.
type HeaderCarrier nats.Header

func (c HeaderCarrier) Get(key string) string {
	v := nats.Header(c).Values(key)
	if len(v) == 0 {
		return ""
	}
	return v[0]
}

func (c HeaderCarrier) Set(key, value string) {
	nats.Header(c).Set(key, value)
}

func (c HeaderCarrier) Keys() []string {
	keys := make([]string, 0, len(c))
	for k := range c {
		keys = append(keys, k)
	}
	return keys
}

// Inject writes the propagator state from ctx into msg.Header, creating the
// header map if absent. Call before publishing so the consumer can re-parent.
func Inject(ctx context.Context, msg *nats.Msg) {
	if msg.Header == nil {
		msg.Header = nats.Header{}
	}
	otel.GetTextMapPropagator().Inject(ctx, HeaderCarrier(msg.Header))
}

// Extract returns ctx with propagator state from msg.Header applied. Call
// before starting the consumer span so it parents to the remote producer.
func Extract(ctx context.Context, msg *nats.Msg) context.Context {
	return ExtractHeader(ctx, msg.Header)
}

// ExtractHeader is Extract over a bare nats.Header — for JetStream consumers,
// which expose headers via jetstream.Msg.Headers() rather than a *nats.Msg.
func ExtractHeader(ctx context.Context, h nats.Header) context.Context {
	if h == nil {
		return ctx
	}
	return otel.GetTextMapPropagator().Extract(ctx, HeaderCarrier(h))
}

// Message is the subset of jetstream.Msg the consumer-span helper needs.
type Message interface {
	Headers() nats.Header
	Subject() string
}

// StartConsumerSpan extracts the propagated trace context from msg's headers
// and opens a consumer span named name on tr, pre-tagged with the standard
// messaging attributes (system=nats, destination=subject). Extra attrs are
// appended. Collapses the extract+start boilerplate shared by every JetStream
// consumer in the service.
func StartConsumerSpan(ctx context.Context, tr trace.Tracer, msg Message, name string, attrs ...attribute.KeyValue) (context.Context, trace.Span) {
	ctx = ExtractHeader(ctx, msg.Headers())
	base := append([]attribute.KeyValue{
		attribute.String("messaging.system", "nats"),
		attribute.String("messaging.destination.name", msg.Subject()),
	}, attrs...)
	return tr.Start(ctx, name, trace.WithSpanKind(trace.SpanKindConsumer), trace.WithAttributes(base...))
}

// Compile-time check that HeaderCarrier satisfies TextMapCarrier.
var _ propagation.TextMapCarrier = HeaderCarrier(nil)

