// Package natsx holds small, dependency-light helpers for working with NATS
// connections and pull consumers. It intentionally depends only on the standard
// library, nats.go, and slogutil so it can be imported by any consumer or serve
// package without creating an import cycle back into core.
package natsx

import (
	"context"
	"log/slog"
	"time"

	"entire.io/slogutil"
	"github.com/nats-io/nats.go"
)

// Drain drains nc and waits (bounded by timeout) for it to flush pending
// acks/publishes and reach CLOSED. nats.go's Conn.Drain() is asynchronous — it
// starts the drain on a background goroutine and returns immediately — so a
// bare Drain() in a shutdown cleanup would let the process exit before the
// flush completes. This installs a ClosedHandler to signal completion, starts
// the drain, and blocks until the connection closes or timeout elapses. name
// labels the connection in the logs so a wedged drain can be attributed.
//
// The connect-time nats.DrainTimeout option caps only the subscription-drain
// phase; nats.go then runs an unconditional ~5s publish flush before closing,
// so the true time-to-CLOSED can exceed that option. timeout here is an
// independent backstop that bounds how long we block — not a guarantee the
// drain finished. Once the consumer loops have joined (COR-923 serve ordering)
// there is nothing left to drain, so on a reachable server this returns in
// milliseconds; the backstop only bites when the server is unreachable.
func Drain(ctx context.Context, name string, nc *nats.Conn, timeout time.Duration) {
	if nc == nil || nc.IsClosed() {
		return
	}

	closed := make(chan struct{})
	nc.SetClosedHandler(func(*nats.Conn) { close(closed) })

	if err := nc.Drain(); err != nil {
		slogutil.Warn(ctx, "NATS drain failed; closing", slog.String("conn", name), slog.String("error", err.Error()))
		nc.Close()
		return
	}

	select {
	case <-closed:
		slogutil.Info(ctx, "NATS drained", slog.String("conn", name))
	case <-time.After(timeout):
		slogutil.Warn(ctx, "NATS drain timed out before close", slog.String("conn", name))
	}
}
package natsx

import (
	"context"
	"errors"
	"log/slog"
	"time"

	"github.com/nats-io/nats.go/jetstream"

	"entire.io/slogutil"
)

// Subscriber is the JetStream consumer-management surface a supervised pull
// consumer binds. jetstream.JetStream satisfies it; tests substitute a fake.
type Subscriber interface {
	CreateOrUpdateConsumer(ctx context.Context, stream string, cfg jetstream.ConsumerConfig) (jetstream.Consumer, error)
}

// PullConsumer is the supervise loop shared by every core pull consumer: it
// create-or-updates a durable on a stream, consumes from it, and re-creates
// after a growing backoff whenever the consume terminates on its own — a deleted
// consumer or a closed connection surfaced via ConsumeContext.Closed() — until
// ctx is cancelled. The jetstream client owns reconnection and idle-heartbeat
// recovery internally; this loop only supervises the terminal cases it surfaces.
//
// PullConsumer owns the mechanism only. The durable contract (Consumer), the
// per-message handling, and each message's ack/nak/term disposition — including
// panic recovery, which stays inside the handler where the per-message span
// lives — are the caller's Handle. Log lines are composed from Name (e.g.
// "email consumer subscribed"); LogFields carries any extra structured context,
// such as the op or filter subject that disambiguates sibling consumers.
type PullConsumer struct {
	// Name prefixes every log line, e.g. "email" or "repo-ops".
	Name string
	// Subscriber create-or-updates the durable on each (re)connect.
	Subscriber Subscriber
	// Stream is the stream the durable binds.
	Stream string
	// Consumer is the durable pull-consumer contract. It is re-applied on every
	// (re)connect, so a drifted tunable reconciles in place.
	Consumer jetstream.ConsumerConfig
	// Handle processes one delivery. It owns the disposition (ack/nak/term) and
	// its own panic recovery, and runs on the nats.go dispatch goroutine.
	Handle func(ctx context.Context, msg jetstream.Msg)
	// FetchBatch caps in-flight deliveries (PullMaxMessages).
	FetchBatch int
	// RetryBackoff is the initial reconnect backoff; RetryBackoffMax caps it.
	RetryBackoff    time.Duration
	RetryBackoffMax time.Duration
	// LogFields are extra structured attributes appended to every log line.
	LogFields []slog.Attr
}

// Run drives the supervise loop until ctx is cancelled.
func (p PullConsumer) Run(ctx context.Context) {
	backoff := p.RetryBackoff
	for {
		if ctx.Err() != nil {
			return
		}
		cons, err := p.Subscriber.CreateOrUpdateConsumer(ctx, p.Stream, p.Consumer)
		if err != nil {
			// Stream-not-found is expected during a rollout where the consumer
			// comes up before its stream has been reconciled (or in a dev cluster
			// without one). Warn rather than Error so on-call isn't paged on
			// routine startup ordering.
			if errors.Is(err, jetstream.ErrStreamNotFound) {
				slogutil.Warn(ctx, p.Name+" stream not yet present, retrying",
					p.attrs(slog.String("stream", p.Stream), slog.String("durable", p.Consumer.Durable))...)
			} else {
				slogutil.Error(ctx, p.Name+" create consumer failed",
					p.attrs(slog.String("error", err.Error()))...)
			}
			if !backoffSleep(ctx, &backoff, p.RetryBackoffMax) {
				return
			}
			continue
		}

		cc, err := cons.Consume(
			func(msg jetstream.Msg) { p.Handle(ctx, msg) },
			jetstream.PullMaxMessages(p.FetchBatch),
			jetstream.ConsumeErrHandler(func(_ jetstream.ConsumeContext, cerr error) {
				slogutil.Warn(ctx, p.Name+" consume error", p.attrs(slog.String("error", cerr.Error()))...)
			}),
		)
		if err != nil {
			slogutil.Error(ctx, p.Name+" consume start failed", p.attrs(slog.String("error", err.Error()))...)
			if !backoffSleep(ctx, &backoff, p.RetryBackoffMax) {
				return
			}
			continue
		}
		slogutil.Info(ctx, p.Name+" consumer subscribed",
			p.attrs(slog.String("durable", p.Consumer.Durable), slog.String("stream", p.Stream))...)
		consumeStart := time.Now()
		// Capture the completion channel while the subscription is live: Closed()
		// returns the same channel each call, so capturing once is equivalent to
		// re-calling it in the select and avoids any post-Stop race.
		closed := cc.Closed()

		select {
		case <-ctx.Done():
			cc.Stop() // the callback is synchronous; an in-flight handler finishes
			return
		case <-closed:
			// Consume terminated on its own — a deleted consumer or a closed
			// connection. Recreate after a backoff, resetting it only if the
			// consume ran healthily for a while first; an immediate close keeps
			// backing off toward RetryBackoffMax instead of recreating at the init
			// interval and hammering a recovering server.
			if time.Since(consumeStart) >= p.RetryBackoffMax {
				backoff = p.RetryBackoff
			}
			if !backoffSleep(ctx, &backoff, p.RetryBackoffMax) {
				return
			}
		}
	}
}

// attrs prepends per-call log attributes to the consumer's LogFields.
func (p PullConsumer) attrs(head ...slog.Attr) []slog.Attr {
	return append(head, p.LogFields...)
}

// backoffSleep waits for the current backoff, then doubles it up to maxBackoff.
// Returns false if ctx is cancelled while waiting, so the caller can stop the
// run loop.
func backoffSleep(ctx context.Context, backoff *time.Duration, maxBackoff time.Duration) bool {
	select {
	case <-ctx.Done():
		return false
	case <-time.After(*backoff):
		*backoff = min(*backoff*2, maxBackoff)
		return true
	}
}

