package natsmsg

import (
	"context"
	"math"

	"github.com/nats-io/nats.go"
	"go.opentelemetry.io/otel"
	"go.opentelemetry.io/otel/propagation"
)

// ExtractTraceContext resumes the trace context a publisher injected into the
// message headers, so publish → consume stitches into one trace. It takes the
// header map rather than the message so it serves both *nats.Msg (msg.Header)
// and jetstream.Msg (msg.Headers()).
func ExtractTraceContext(ctx context.Context, h nats.Header) context.Context {
	if h == nil {
		return ctx
	}
	return otel.GetTextMapPropagator().Extract(ctx, HeaderCarrier(h))
}

// HeaderCarrier adapts nats.Header to the OTel TextMapCarrier contract so
// trace context propagates over JetStream (publish → consume).
type HeaderCarrier nats.Header

func (c HeaderCarrier) Get(key string) string {
	v := nats.Header(c).Values(key)
	if len(v) == 0 {
		return ""
	}
	return v[0]
}

func (c HeaderCarrier) Set(key, value string) { nats.Header(c).Set(key, value) }

func (c HeaderCarrier) Keys() []string {
	keys := make([]string, 0, len(c))
	for k := range c {
		keys = append(keys, k)
	}
	return keys
}

var _ propagation.TextMapCarrier = HeaderCarrier(nil)

// ClampToInt64 narrows a JetStream sequence / delivery count (uint64 on the
// wire) to the int64 OTel attributes take, saturating instead of wrapping.
func ClampToInt64(v uint64) int64 {
	if v > math.MaxInt64 {
		return math.MaxInt64
	}
	return int64(v)
}
// Package natsmsg holds small JetStream message helpers shared by the
// hand-rolled pull consumers (permswebhook, repoops).
package natsmsg

import (
	"sync"
	"time"
)

// keepInProgressMaxTicks caps the total AckWait extension at ~5×AckWait
// (ticks fire at AckWait/3). The heartbeat exists so a long handler that IS
// making progress — a whole-installation teardown fan-out, a multi-GB
// data-plane purge — doesn't get redelivered into a concurrent duplicate;
// it must NOT remove the broker's liveness failsafe entirely, or a wedged
// handler (hung I/O with no deadline) would pin its delivery to the wedged
// replica forever. Past the cap the extension stops and AckWait expiry
// redelivers to a healthy replica sharing the durable.
const keepInProgressMaxTicks = 15

// KeepInProgress calls inProgress at ackWait/3 until stop is called, resetting
// the broker's redelivery timer while a long handler runs. The extension is
// capped (keepInProgressMaxTicks) — see the constant for why.
//
// inProgress wraps the message's InProgress call — func() error { return
// msg.InProgress() }. The func() error callback keeps this helper decoupled
// from the jetstream package.
//
// A non-positive interval (zero ackWait on a hand-built consumer; New
// defaults it everywhere real) returns a no-op stop.
//
// stop is idempotent and blocks until the ticker goroutine has exited, so
// no InProgress can race a terminal disposition (Ack/Nak/Term) issued
// after it returns.
func KeepInProgress(inProgress func() error, ackWait time.Duration) (stop func()) {
	interval := ackWait / 3
	if interval <= 0 {
		return func() {}
	}
	done := make(chan struct{})
	finished := make(chan struct{})
	go func() {
		defer close(finished)
		ticker := time.NewTicker(interval)
		defer ticker.Stop()
		for ticks := 0; ; {
			select {
			case <-done:
				return
			case <-ticker.C:
				ticks++
				if ticks > keepInProgressMaxTicks {
					return
				}
				if err := inProgress(); err != nil {
					// A delivery that can't be extended (no JetStream
					// reply subject, or already terminally disposed)
					// won't start succeeding on a later tick; stop
					// instead of spinning. The real failure surfaces
					// on the terminal Ack/Nak/Term.
					return
				}
			}
		}
	}()
	var once sync.Once
	return func() {
		once.Do(func() { close(done) })
		<-finished
	}
}
package natsmsg

import (
	"context"
	"fmt"
	"strconv"
	"time"

	"github.com/nats-io/nats.go"
	"github.com/nats-io/nats.go/jetstream"
)

// dlqPublishTimeout bounds one dead-letter PublishMsg. The consume context has
// no deadline, and PublishMsg waits for the PubAck indefinitely; without a
// bound a NATS blip would hang the handler (and, since fetchBatch keeps a slot
// one-in-flight, stall the consumer) instead of failing the capture loudly.
const dlqPublishTimeout = 15 * time.Second

// DLQ provenance headers added to the captured copy so a replay tool (or a
// human) can see why and from where a message was dead-lettered.
const (
	DLQReasonHeader    = "Nats-Dlq-Reason"
	DLQOriginHeader    = "Nats-Dlq-Origin-Subject"
	DLQDeliveredHeader = "Nats-Dlq-Delivered"
	DLQStreamSeqHeader = "Nats-Dlq-Stream-Seq"
)

// DLQPublisher is the publish surface DeadLetter needs — satisfied by
// nats.JetStreamContext. Kept minimal so wiring can hand it the same
// JetStreamContext the per-cell publishers already hold, and tests can stub it.
type DLQPublisher interface {
	PublishMsg(m *nats.Msg, opts ...nats.PubOpt) (*nats.PubAck, error)
}

// SubjectToken sanitizes s into a single valid NATS subject token. NATS tokens
// cannot contain spaces, dots, or wildcards, so every character outside
// [a-z0-9_-] is replaced with '_' (and letters are lowercased). Use it to turn a
// human-readable dead-letter reason ("bad completion payload") into a subject
// token ("bad_completion_payload") — publishing to an unsanitized reason would
// fail, so the caller would never Ack the poison off the WorkQueue (COR-944).
func SubjectToken(s string) string {
	// Iterate bytes, not runes: we only keep ASCII [a-z0-9_-] and map everything
	// else (including every byte of a multi-byte rune) to '_', so a byte loop is
	// both correct and free of a rune->byte narrowing conversion.
	b := make([]byte, 0, len(s))
	for i := range len(s) {
		c := s[i]
		switch {
		case c >= 'a' && c <= 'z', c >= '0' && c <= '9', c == '_', c == '-':
			b = append(b, c)
		case c >= 'A' && c <= 'Z':
			b = append(b, c-'A'+'a')
		default:
			b = append(b, '_')
		}
	}
	if len(b) == 0 {
		return "unknown"
	}
	return string(b)
}

// DeadLetter republishes a poison message to dlqSubject, preserving its payload
// and headers and adding Nats-Dlq-* provenance (reason, origin subject,
// delivery count, stream sequence).
//
// It exists because repo_ops_v1 is a WorkQueue: a message leaves the stream
// only on a positive Ack. Term and MaxDeliver-exhaustion do NOT delete it — it
// lingers un-acked until StreamMaxAge, pinning the oldest-pending-age gauge
// (COR-944). So a consumer that can never process a message must DeadLetter it
// and then Ack the original.
//
// Returns an error if the republish fails; on error the caller MUST NOT Ack —
// Nak or leave the message so the poison is never dropped without a captured
// copy. Publishing is bounded by dlqPublishTimeout regardless of ctx's deadline.
func DeadLetter(ctx context.Context, pub DLQPublisher, dlqSubject string, msg jetstream.Msg, reason string) error {
	hdr := nats.Header{}
	for k, v := range msg.Headers() {
		hdr[k] = append([]string(nil), v...)
	}
	hdr.Set(DLQReasonHeader, reason)
	hdr.Set(DLQOriginHeader, msg.Subject())
	if meta, err := msg.Metadata(); err == nil && meta != nil {
		hdr.Set(DLQDeliveredHeader, strconv.FormatUint(meta.NumDelivered, 10))
		hdr.Set(DLQStreamSeqHeader, strconv.FormatUint(meta.Sequence.Stream, 10))
	}

	out := &nats.Msg{Subject: dlqSubject, Data: msg.Data(), Header: hdr}

	pubCtx, cancel := context.WithTimeout(ctx, dlqPublishTimeout)
	defer cancel()
	if _, err := pub.PublishMsg(out, nats.Context(pubCtx)); err != nil {
		return fmt.Errorf("dead-letter publish to %q: %w", dlqSubject, err)
	}
	return nil
}

