     1	// Package otelnats propagates W3C trace context through NATS message headers
     2	// so consumer spans can parent to the remote producer span.
     3	package otelnats
     4	
     5	import (
     6		"context"
     7	
     8		"github.com/nats-io/nats.go"
     9		"go.opentelemetry.io/otel"
    10		"go.opentelemetry.io/otel/propagation"
    11	)
    12	
    13	// HeaderCarrier adapts nats.Header to propagation.TextMapCarrier so the
    14	// configured propagator can inject/extract traceparent and baggage.
    15	type HeaderCarrier nats.Header
    16	
    17	func (c HeaderCarrier) Get(key string) string {
    18		v := nats.Header(c).Values(key)
    19		if len(v) == 0 {
    20			return ""
    21		}
    22		return v[0]
    23	}
    24	
    25	func (c HeaderCarrier) Set(key, value string) {
    26		nats.Header(c).Set(key, value)
    27	}
    28	
    29	func (c HeaderCarrier) Keys() []string {
    30		keys := make([]string, 0, len(c))
    31		for k := range c {
    32			keys = append(keys, k)
    33		}
    34		return keys
    35	}
    36	
    37	// Inject writes the propagator state from ctx into msg.Header, creating the
    38	// header map if absent. Call before nats.JetStreamContext.PublishMsg.
    39	func Inject(ctx context.Context, msg *nats.Msg) {
    40		if msg.Header == nil {
    41			msg.Header = nats.Header{}
    42		}
    43		otel.GetTextMapPropagator().Inject(ctx, HeaderCarrier(msg.Header))
    44	}
    45	
    46	// Extract returns ctx with propagator state from msg.Header applied. Call
    47	// before starting the consumer span so it parents to the remote producer.
    48	func Extract(ctx context.Context, msg *nats.Msg) context.Context {
    49		if msg.Header == nil {
    50			return ctx
    51		}
    52		return otel.GetTextMapPropagator().Extract(ctx, HeaderCarrier(msg.Header))
    53	}
    54	
    55	// Compile-time check that HeaderCarrier satisfies TextMapCarrier.
    56	var _ propagation.TextMapCarrier = HeaderCarrier(nil)
