   260	// broadcast publishes one row's stored (subject, payload) with Nats-Msg-Id =
   261	// row.MsgID into EVERY destination jurisdiction CONCURRENTLY, returning nil only
   262	// when all of them PubAck. Parallel across regions (safe — per-row, so per-shard
   263	// id order between rows is untouched) so a backlog fans to N regions in one RTT
   264	// rather than N; matters when the Phase-5 backfill bursts the outbox. On any
   265	// destination failure the joined error is returned so the caller keeps the row for
   266	// next tick; the destinations that DID ack collapse the re-publish under the
   267	// stream's duplicate window. Each publish is bounded by publishTimeout so a down
   268	// region fails fast rather than stalling the drain.
   269	func (r *Relay) broadcast(ctx context.Context, row store.OutboxRow) error {
   270		var (
   271			wg   sync.WaitGroup
   272			mu   sync.Mutex
   273			errs []error
   274		)
   275		for jur, pub := range r.dests {
   276			wg.Add(1)
   277			go func() {
   278				defer wg.Done()
   279				msg := &nats.Msg{
   280					Subject: row.Subject,
   281					Header:  nats.Header{nats.MsgIdHdr: []string{row.MsgID}},
   282					Data:    row.Payload,
   283				}
   284				pubCtx, cancel := context.WithTimeout(ctx, publishTimeout)
   285				_, err := pub.PublishMsg(pubCtx, msg)
   286				cancel()
   287				if err != nil {
   288					mu.Lock()
   289					errs = append(errs, fmt.Errorf("jurisdiction %q: %w", jur, err))
   290					mu.Unlock()
   291				}
   292			}()
   293		}
   294		wg.Wait()
   295		return errors.Join(errs...)
   296	}
