   291	// faultBackoff is the consecutive-Fetch-fault delay. Bounded so a
   292	// persistently-broken stream doesn't spin.
   293	func faultBackoff(n int) time.Duration {
   294		if n <= 0 {
   295			return time.Second
   296		}
   297		d := time.Second << uint(n-1)
   298		if d > 60*time.Second {
   299			d = 60 * time.Second
   300		}
   301		return d
   302	}
   303	
   304	// backoffFor returns a per-message delay that grows with redelivery
   305	// count. Caps at 5 minutes — the consumer's MaxDeliver eventually
   306	// kicks the message to the DLQ even on persistent failure.
   307	func backoffFor(msg jetstream.Msg) time.Duration {
   308		meta, err := msg.Metadata()
   309		if err != nil {
   310			return 5 * time.Second
   311		}
   312		// 1, 2, 4, 8, 16, 32, 64, 128, 256 seconds, then capped at 300s.
   313		delivery := meta.NumDelivered
   314		if delivery == 0 {
   315			delivery = 1
   316		}
   317		d := time.Second
   318		for i := uint64(1); i < delivery && d < 300*time.Second; i++ {
   319			d *= 2
   320		}
   321		if d > 300*time.Second {
   322			d = 300 * time.Second
   323		}
   324		return d
   325	}
   620			span.RecordError(err)
   621			// Final delivery: JetStream won't redeliver past jobMaxDeliver, and the
   622			// index-job streams are WorkQueue with no DLQ, so nak'ing again would let the
   623			// job vanish silently (the poison-job failure mode — e.g. a repo whose walk
   624			// keeps timing out). The ERROR + counter (tagged by kind) are the load-bearing
   625			// signal — they turn a silent drop into an alertable event. On the last attempt
   626			// a nak and a term both drop the message; term makes the intent explicit (and
   627			// emits a distinct MSG_TERMINATED advisory) rather than looking like one more
   628			// backoff. This handles only the delivered-and-failed path; a job that reaches
   629			// the limit via redelivery timeout (a mid-job crash, no terminal op) is caught
   630			// instead by the MAX_DELIVERIES advisory reaper (see startExhaustReaper), which
   631			// emits the same counter + ERROR. See the exhausted-job metric in metrics.go.
   632			if meta, mErr := msg.Metadata(); mErr == nil && meta.NumDelivered >= jobMaxDeliver {
