func authenticator(cfg config.Common) *auth.Authenticator {
	if cfg.JurisdictionAudience == "" {
		slog.Warn("ENTIRE_JURISDICTION_AUDIENCE unset: identity-token audience check fails closed — every token is rejected; set it to this cell's jurisdiction host in real deployments")
	}
