}

// buildClusterConns dials one NATS connection per configured remote
// jurisdiction, opens a JetStream context on each (incl. local), and returns
// the jurisdiction->JetStream map for the forwarder plus the dialed remote
// conns (for lifecycle/drain). The user_activity_v1 and repo_index_jobs streams
// are provisioned declaratively in fleet (apps/nats-streams, nack), not created
// here. There is no supercluster: the local jurisdiction always maps to localNC
// (already dialed for ingest/consume), so a single-region deployment needs no
// ACTIVITY_NATS_REGIONS entry. A user_activity event is account-addressed and
// an account's residency unit is its jurisdiction, so the forwarder routes by
// jurisdiction, not cluster. On any error, conns dialed so far are drained.
func buildClusterConns(ctx context.Context, cfg *config.RepoActivityConfig, localNC *nats.Conn) (map[string]forwarder.JSPublisher, []*nats.Conn, error) {
	drainAll := func(cs []*nats.Conn) {
		for _, c := range cs {
			nuts.Drain(ctx, c, c.Opts.Name, nil, natsDrainBackstop)
		}
	}
	localJS, err := jetstream.New(localNC)
	if err != nil {
		return nil, nil, fmt.Errorf("jetstream.New (local): %w", err)
	}
	conns := map[string]forwarder.JSPublisher{string(cfg.Jurisdiction): localJS}
	var remotes []*nats.Conn
	for jurisdiction, url := range cfg.NATSRegions {
		if jurisdiction == string(cfg.Jurisdiction) {
			continue // local jurisdiction already mapped to localNC
		}
		// A remote region's availability must not gate this worker's startup
		// or survival: WithRetryOnFailedConnect keeps a down region from
		// failing construction (and crashlooping local ingest), and
		// nuts.Connect's reconnect-forever keeps a longer outage from
		// permanently closing the connection. Until the link is back,
		// publishes into that jurisdiction fail within the forwarder's
		// publish timeout (nats.go buffers publishes on a reconnecting conn
		// rather than erroring, so the forwarder bounds the PubAck wait
		// itself) and the source message naks/redelivers. Lifecycle logs
		// carry the jurisdiction via the connection name.
		rc, err := nuts.Connect(ctx, url,
			nuts.WithName("activity-fwd-"+jurisdiction),
			nuts.WithRetryOnFailedConnect(),
		)
		if err != nil {
			drainAll(remotes)
			return nil, nil, fmt.Errorf("dial jurisdiction %q nats (%s): %w", jurisdiction, url, err)
		}
		rjs, err := jetstream.New(rc)
		if err != nil {
			_ = rc.Drain()
			drainAll(remotes)
			return nil, nil, fmt.Errorf("jetstream.New (%s): %w", jurisdiction, err)
		}
		conns[jurisdiction] = rjs
		remotes = append(remotes, rc)
	}
	return conns, remotes, nil
}

