type mirrorConsumerConfig struct {
	clusterID    string
	jurisdiction string
}

func loadMirrorConsumerConfig(getenv func(string) string) (mirrorConsumerConfig, error) {
	cfg := mirrorConsumerConfig{
		clusterID:    getenv("ENTIRE_MIRROR_CLUSTER_ID"),
		jurisdiction: getenv("ENTIRE_MIRROR_JURISDICTION"),
	}
	if cfg.clusterID == "" || cfg.jurisdiction == "" {
		return cfg, fmt.Errorf("ENTIRE_MIRROR_CLUSTER_ID and ENTIRE_MIRROR_JURISDICTION are required")
	}
	return cfg, nil
}

// resolveTargetURL picks the entiredb target URL for the worker. An explicit
// ENTIRE_TARGET_URL takes precedence so local dev (e.g. http://localhost:8080)
// and node-specific debugging (e.g. https://node1.royalcanin.partial.to) keep
// working unchanged. Otherwise the steady-state URL is derived as
// https://<ENTIRE_MIRROR_CLUSTER_ID>.<ENTIRE_ENV>, which is what fleet
// configures in production.
//
// This URL is the cluster's PUBLIC identity. The URL the worker actually
// dials for git pushes may diverge (see resolveTargetTransportURL): in
// prod, fleet sets ENTIRE_TARGET_INTERNAL_URL to the cluster's svctok mTLS
// endpoint, where the worker's client certificate is the whole credential
// (COR-536).
func resolveTargetURL(getenv func(string) string, clusterID string) (string, error) {
	if u := getenv("ENTIRE_TARGET_URL"); u != "" {
		return u, nil
	}
	env := getenv("ENTIRE_ENV")
	if env == "" {
		return "", errors.New("ENTIRE_TARGET_URL or ENTIRE_ENV is required")
	}
	if clusterID == "" {
		return "", errors.New("ENTIRE_MIRROR_CLUSTER_ID is required to derive target URL from ENTIRE_ENV")
	}
	return fmt.Sprintf("https://%s.%s", clusterID, env), nil
}

// resolveTargetTransportURL picks the URL the syncer's HTTP client
// dials. ENTIRE_TARGET_INTERNAL_URL, when set, routes git pushes to
// the cluster's strict-mTLS svctok endpoint (e.g.
// https://svctok.royalcanin.partial.internal:8281). Falls back to the
// public URL when unset so dev / single-URL setups keep working.
func resolveTargetTransportURL(getenv func(string) string, publicURL string) string {
	if u := getenv("ENTIRE_TARGET_INTERNAL_URL"); u != "" {
		// Strip a trailing slash so syncer.targetURL ("%s/git/repo/%s")
		// doesn't compose //git/repo paths. Matches the convention in
		// resolveSourceBaseURL.
		return strings.TrimSuffix(u, "/")
	}
	return publicURL
}

// svctokClusterParent strips the leading "svctok." from a transport host
// to yield the parent suffix clusterTransport matches against. Called only
// when the transport URL diverges from the public URL — the divergence
// detection lives at the call site so it can use the URL strings directly
// (a host-equality check would miss port-only or scheme-only divergence
// while mTLS is still active, which would silently route the cross-host
// /info/refs 307 off the mTLS transport).
//
// entiredb's HandleInfoRefsDiscovery (server/githttp/repo.go) 307s
// non-hosting svctok requests to nodeN.<cluster>.partial.internal — NOT a
// subdomain of svctok.<cluster>.… The subsequent receive-pack POST must
// present the client cert (it is the whole credential on this listener), so
// clusterTransport needs a matcher covering both the svctok endpoint and
// the per-node hosts. The stripped parent covers both.
//
// Errors when the host doesn't begin with "svctok." — silent handshake
// rejections on 90%+ of pushes is the failure mode we're trying to avoid.
func svctokClusterParent(transportHost string) (string, error) {
	parent, ok := strings.CutPrefix(transportHost, "svctok.")
	if !ok {
		return "", fmt.Errorf(
			"ENTIRE_TARGET_INTERNAL_URL host %q must begin with \"svctok.\" when it diverges "+
				"from ENTIRE_TARGET_URL — mirror-worker derives the cluster matcher by "+
				"stripping that prefix to cover both the svctok endpoint and per-node hosts "+
				"entiredb 307s to", transportHost)
	}
	if parent == "" {
		return "", fmt.Errorf("ENTIRE_TARGET_INTERNAL_URL host %q has empty parent after stripping \"svctok.\"", transportHost)
	}
	return parent, nil
}

// resolveSourceBaseURL picks the GitHub base URL the syncer composes its
// source-fetch URL against. Defaults to https://github.com so production
// behaviour is unchanged; ENTIRE_GITHUB_BASE_URL=http://mockgithub:9001
// (or similar) repoints the fetch path at a mock for load testing.
// A single trailing slash is stripped so the syncer's "%s/%s/%s" format
// doesn't produce a double slash.
func resolveSourceBaseURL(getenv func(string) string) string {
	raw := getenv("ENTIRE_GITHUB_BASE_URL")
	if raw == "" {
		return "https://github.com"
	}
	return strings.TrimSuffix(raw, "/")
}

// parseDurationEnv reads a Go duration env var, falling back to def when unset,
// empty, or unparseable (logged). "0" parses to 0, which disables age eviction
// (the WithMaxEntryAge guard is `> 0`).
func parseDurationEnv(key string, def time.Duration) time.Duration {
	raw := os.Getenv(key)
	if raw == "" {
		return def
	}
	d, err := time.ParseDuration(raw)
	if err != nil {
		slog.Warn("Invalid duration env var; using default",
			slog.String("key", key), slog.String("value", raw), slog.Duration("default", def))
		return def
	}
	return d
}

func main() {
	if err := run(); err != nil {
		slog.Error("worker failed", slog.Any("error", err))
		os.Exit(1)
	}
}

func run() error {
	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stop()

	// Name this service in git-sync's User-Agent and git-protocol agent=
	// capability: "mirror-worker/<sha> git-sync/<ver> go-git/<ver>". Without
	// it, pushes are attributed to the bare library ("git-sync/dev ...") in
	// server access logs and APM.
	gitsync.SetIdentity("mirror-worker", version.Version)

	otelShutdown, err := otelsetup.Setup(ctx, otelsetup.Config{
		ServiceName:    "mirror-worker",
		ServiceVersion: version.Version,
	})
	if err != nil {
		return fmt.Errorf("setup opentelemetry: %w", err)
	}
	defer otelsetup.Shutdown(otelShutdown)

	natsURL := os.Getenv("ENTIRE_NATS_URL")
	if natsURL == "" {
		return fmt.Errorf("ENTIRE_NATS_URL is required")
	}
	listenAddr := svchttp.ListenAddr(os.Getenv)

	mirrorCfg, err := loadMirrorConsumerConfig(os.Getenv)
	if err != nil {
		return err
	}
	publicURL, err := resolveTargetURL(os.Getenv, mirrorCfg.clusterID)
	if err != nil {
		return err
		return err
	}
	transportURL := resolveTargetTransportURL(os.Getenv, publicURL)
	transportHost, err := targetBaseURLHost(transportURL)
	if err != nil {
		return err
	}
	// Cluster matcher must anticipate entiredb's cross-host /info/refs
	// 307s whenever the transport URL differs from the public URL,
	// even if hostnames coincidentally match (port-only or scheme-only
	// divergence) — mTLS is still active and the 307 target is determined
	// by entiredb's HTTPInternalAdvertiseAddrs, not by our URLs. Gate on
	// string equality so any drift triggers the svctok-prefix strip.
	clusterMatchHost := transportHost
	if transportURL != publicURL {
		parent, err := svctokClusterParent(transportHost)
		if err != nil {
			return err
		}
		clusterMatchHost = parent
	}
	// entire-core internal auth config. The worker talks to entire-core's
	// mTLS listener using the cert in ENTIRE_INTERNAL_TLS_*_FILE. fleet's
	// _lib/internal-tls component populates the cert env vars; the URL is
	// per-region (entire-core's :8281 mTLS listener).
	coreInternalURL := os.Getenv("ENTIRE_CORE_INTERNAL_URL")
	if coreInternalURL == "" {
		return errors.New("ENTIRE_CORE_INTERNAL_URL is required")
	}
	tlsCertFile := os.Getenv("ENTIRE_INTERNAL_TLS_CERT_FILE")
	tlsKeyFile := os.Getenv("ENTIRE_INTERNAL_TLS_KEY_FILE")
	tlsCAFile := os.Getenv("ENTIRE_INTERNAL_TLS_CA_FILE")

	metrics, err := newWorkerMetrics()
	if err != nil {
		return fmt.Errorf("initialize metrics: %w", err)
	}

	// Coordinate graceful shutdown: cancel the background loops, join them, and
	// only THEN drain NATS — the ordering that keeps the drain from racing an
	// in-flight Fetch and logging shutdown noise (COR-923).
	g := nuts.NewShutdownGroup(ctx)
	defer g.Shutdown()

	// Attach the advisory-backstop permission handler at dial time: a rejected
	// advisory SUBSCRIBE surfaces only via the connection's async ErrHandler (the
	// subscribe call itself succeeds), so wiring it here is the only way to detect
	// a missing grant. It also gives every other async NATS error a warn log.
	nc, err := nuts.Connect(ctx, natsURL,
		nuts.WithName("mirror-worker"),
		nuts.WithNATSOptions(nats.ErrorHandler(advisoryPermErrorHandler(metrics))),
	)
	if err != nil {
		return fmt.Errorf("connect to NATS: %w", err)
	}
	g.AddConn("mirror-worker", nc)

	js, err := nc.JetStream()
	if err != nil {
		return fmt.Errorf("create JetStream context: %w", err)
	}

	// One shared cert source (an http.RoundTripper) for every mTLS channel:
	// the git push and the App minter. The worker's SPIFFE certificate is
	// its whole credential to entiredb — no token is minted for the push
	// path; entiredb's svctok listener authorizes the workload cert-only
	// from its inbound write-mirror allowlist (COR-536). The reloader
	// routes every request through a transport pinned to the current leaf
	// and swaps to a fresh one on cert-manager rotation.
	reloader, err := authmtls.NewReloader(tlsCertFile, tlsKeyFile, tlsCAFile)
	if err != nil {
		return fmt.Errorf("load internal mTLS cert: %w", err)
	}
	// Begin polling for cert-manager rotations; stops when ctx is canceled.
	go reloader.Watch(ctx, authmtls.DefaultReloadInterval)

	// When ENTIRE_TARGET_INTERNAL_URL points at the cluster's svctok :8281
	// endpoint, push traffic must ride strict mTLS: the listener demands a
	// client cert at the handshake, and that cert is the entire credential.
	var targetTransport http.RoundTripper
	var repoAdmin defaultBranchSetter
	if transportURL != publicURL {
		targetTransport = reloader
		// RepoAdmin.SetDefaultBranch is served on the same svctok listener
		// and authorized by the same cert-only workload identity as the git
		// push, so the client shares the reloader. Only wired on this
		// branch: the public ALB doesn't mount RepoAdmin, and without the
		// client the syncer's default-branch reconcile stays disabled.
		repoAdmin = repoadminv1connect.NewRepoAdminClient(authmtls.NewClient(reloader), transportURL)
		slog.Info("Mirror target: strict-mTLS svctok, cert-only auth",
			slog.String("transport_url", transportURL),
			slog.String("transport_host", transportHost),
			slog.String("public_url", publicURL),
			slog.String("cluster_match_host", clusterMatchHost))
	} else {
		slog.Info("Mirror target: public ALB (no internal URL configured); default-branch reconcile disabled",
			slog.String("transport_url", transportURL),
			slog.String("cluster_match_host", clusterMatchHost))
	}

	// GitHub App installation tokens are minted via entire-core's STS using
	// the same internal mTLS channel (the shared reloader); entire-core
	// authorizes the mint against the mirror metadata for the target repo
	// before calling GitHub on the worker's behalf.
	appMinterClient := authmtls.NewClient(reloader)
	appMinter := coreapp.NewMinter(coreapp.Config{
		IssuerURL:  coreInternalURL,
		HTTPClient: appMinterClient,
	})
	slog.Info("GitHub App tokens via entire-core STS",
		slog.String("issuer_url", coreInternalURL))

	sourceBaseURL := resolveSourceBaseURL(os.Getenv)
	slog.Info("Source git base URL", slog.String("url", sourceBaseURL))

	cfg := syncerConfig{
		sourceBaseURL:     sourceBaseURL,
		targetBaseURL:     transportURL,
		targetClusterHost: clusterMatchHost,
		githubApp:         appMinter,
		targetTransport:   targetTransport,
		metrics:           metrics,
		repoAdmin:         repoAdmin,
	}

	s, err := newSyncer(cfg)
	if err != nil {
		return fmt.Errorf("initialize syncer: %w", err)
	}

	// Bind the mirror-sync failure index (KV bucket declared in fleet and
	// reconciled by nack; the worker binds, never creates). Degrade gracefully:
	// if the bucket can't be bound — e.g. a fresh-cluster rollout race where the
	// worker starts before nack reconciles it — log loudly and run without it
	// rather than crash-loop. Syncing is the worker's core job; failure-recording
	// is an add-on, and a restart re-binds.
	failBucket := os.Getenv("ENTIRE_FAILURE_INDEX_BUCKET")
	if failBucket == "" {
		failBucket = failindex.DefaultBucket
	}
	// failureIndex is an interface, so bind into a typed local and assign only on
	// success — a nil *failindex.Index stored in the interface would be non-nil
	// and panic the nil-guarded record/clear helpers.
	var failIdx failureIndex
	// onCorrupt surfaces the otherwise-silent recovery from an unreadable KV
	// entry (corruption / pre-Version1 schema): count it + log the ULID. Keeps
	// pkg/failindex metrics-free.
	onCorrupt := func(ulid string, op failindex.CorruptOp) {
		// Message tracks what actually happened: record OVERWRITES the bad entry
		// fresh (losing history); clear LEAVES it in place (clear skipped).
		msg := "Failure-index entry unreadable; left in place (clear skipped)"
		if op == failindex.CorruptOpRecord {
			msg = "Failure-index entry unreadable; overwritten fresh (prior triage history lost)"
		}
		slog.ErrorContext(ctx, msg, slog.String("target_ulid", ulid), slog.String("op", string(op)))
		metrics.recordCorruptReset(ctx, string(op))
	}
	// Age-based eviction: drop an entry resident past maxAge so the re-kicker
	// stops re-driving a stuck repo — the backstop the bucket TTL can't provide
	// (re-records refresh the message). Not a permanent tombstone: a dead repo
	// stays evicted (the re-kicker can't re-add), but a still-trafficked-failing
	// repo re-enters on its next real failure (by design). ENTIRE_FAILINDEX_MAX_
	// ENTRY_AGE is a Go duration; default 168h (7d); "0" disables. The drop is
	// loud (WARN + evicted metric); recovery of an evicted repo falls to L2.
	maxEntryAge := parseDurationEnv("ENTIRE_FAILINDEX_MAX_ENTRY_AGE", 168*time.Hour)
	onEvict := func(ulid string, age time.Duration) {
		slog.WarnContext(ctx, "Failure-index entry evicted: failing past max age, giving up (recover via L2 if still needed)",
			slog.String("target_ulid", ulid), slog.Duration("age", age), slog.Duration("max_age", maxEntryAge))
		metrics.recordEvicted(ctx)
	}
	if idx, openErr := failindex.Open(js, failBucket,
		failindex.WithCorruptHandler(onCorrupt),
		failindex.WithMaxEntryAge(maxEntryAge),
		failindex.WithEvictHandler(onEvict),
	); openErr != nil {
		slog.Error("Failure index unavailable; terminal failures will not be recorded until restart",
			slog.String("bucket", failBucket), slog.Any("error", openErr))
	} else {
		failIdx = idx
		slog.Info("Failure index bound", slog.String("bucket", failBucket))
	}
	// Publish the bound/unbound state so an alert can fire on bound==0 even
	// while no failures are occurring (depth/recorded would otherwise stay flat).
	metrics.recordIndexBound(ctx, failIdx != nil)

	// Completion publisher: on a terminal sync the worker publishes
	// the mirror_done op on the SAME in-cell NATS (js) so the co-located regional
	// entire-core flips mirror_repos.status. The stream is owned declaratively
	// by fleet (apps/nats-streams); the worker only publishes.
	c := &consumer{
		js:           js,
		clusterID:    mirrorCfg.clusterID,
		jurisdiction: mirrorCfg.jurisdiction,
		syncer:       s,
		metrics:      metrics,
		failidx:      failIdx,
		donePub:      donejobs.NewPublisher(js),
		syncTimeout:  parseDurationEnv("ENTIRE_WORKER_SYNC_TIMEOUT", defaultSyncTimeout),
	}

	// Backlog gauge: observe the worker's durable consumer depth (NumPending /
	// NumAckPending) on each collection. Derive the durable from the SAME helper
	// the consume loop subscribes through so the gauge can't report a different
	// consumer than the one we drain (and the one KEDA scales on). A registration
	// failure here is a metrics wiring bug, not a runtime degradation (the
	// per-cycle ConsumerInfo errors degrade gracefully inside the callback), so
	// surface it.
	durable := mirrorConsumerDurable(mirrorCfg.jurisdiction, mirrorCfg.clusterID)
	if err := metrics.registerPendingGauge(js, gitjobs.StreamName, durable); err != nil {
		return fmt.Errorf("register pending gauge: %w", err)
	}

	g.Go(func(ctx context.Context) { c.run(ctx) })
	slog.Info("Mirror consumer started",
		slog.String("cluster_id", mirrorCfg.clusterID),
		slog.String("jurisdiction", mirrorCfg.jurisdiction),
		slog.Duration("sync_timeout", c.syncTimeout),
	)

	// Crash backstop: record terminal failures the in-process path missed when a
	// pod died mid-handler, off the JetStream MAX_DELIVERIES/MSG_TERMINATED
	// advisories. No-ops when the index is unbound (logs and returns).
	g.Go(func(ctx context.Context) { runAdvisoryBackstop(ctx, nc, js, failIdx, metrics) })

	mux := svchttp.NewMux(func() (bool, string) {
		if !nc.IsConnected() {
			return false, "NATS disconnected"
		}
		return true, ""
	})
	return svchttp.Serve(ctx, listenAddr, mux)
}
