// Package svchttp is the shared HTTP endpoint runtime for the long-running
// binaries: the GET /healthz + GET /readyz mux every service exposes, and a
// serve loop that drains gracefully when the process context is canceled.
// Each main keeps its own readiness policy (what gates /readyz is a
// per-service decision, documented at the call site) and delegates the
// server mechanics here.
package svchttp

import (
	"context"
	"errors"
	"fmt"
	"log/slog"
	"net"
	"net/http"
	"time"
)

// readHeaderTimeout bounds the request-header read on the default server.
// The health endpoints carry no body; webhook-ingest, which accepts real
// payloads, builds its own fully-timed-out server and uses ServeServer.
const readHeaderTimeout = 5 * time.Second

// shutdownTimeout bounds the graceful drain after the process context is
// canceled, so a wedged connection can't stall exit past k8s' termination
// grace. The drain is awaited (unlike the pre-extraction fire-and-forget
// goroutine) so an in-flight request — a webhook-ingest delivery mid-publish —
// completes before main proceeds to its NATS drains; for the health-only
// servers active requests finish in microseconds, so the await is free.
const shutdownTimeout = 10 * time.Second

// ReadyFunc reports whether the service should pass its readiness probe.
// reason is served as the 503 body when not ready, so `kubectl` output and
// probe logs name the failing condition.
type ReadyFunc func() (ok bool, reason string)

// NewMux returns a mux serving GET /healthz (always 200 — liveness is "the
// process responds") and GET /readyz gated on ready. Callers may register
// additional routes on the returned mux.
func NewMux(ready ReadyFunc) *http.ServeMux {
	mux := http.NewServeMux()
	mux.HandleFunc("GET /healthz", func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(http.StatusOK)
	})
	mux.HandleFunc("GET /readyz", func(w http.ResponseWriter, r *http.Request) {
		if ok, reason := ready(); !ok {
			http.Error(w, reason, http.StatusServiceUnavailable)
			return
		}
		w.WriteHeader(http.StatusOK)
	})
	return mux
}

// ListenAddr returns the configured LISTEN_ADDR, defaulting to ":8080".
func ListenAddr(getenv func(string) string) string {
	if addr := getenv("LISTEN_ADDR"); addr != "" {
		return addr
	}
	return ":8080"
}

// Serve serves handler on addr with the baseline header timeout until ctx is
// canceled, then drains gracefully. Returns nil on a clean shutdown.
func Serve(ctx context.Context, addr string, handler http.Handler) error {
	return ServeServer(ctx, &http.Server{
		Addr:              addr,
		Handler:           handler,
		ReadHeaderTimeout: readHeaderTimeout,
	})
}

// ServeServer is Serve for a caller-built server (custom timeout policy).
func ServeServer(ctx context.Context, srv *http.Server) error {
	ln, err := net.Listen("tcp", srv.Addr)
	if err != nil {
		return fmt.Errorf("http server: %w", err)
	}
	return serveListener(ctx, srv, ln)
}

func serveListener(ctx context.Context, srv *http.Server, ln net.Listener) error {
	// Log the configured addr (what the old per-main code logged and what
	// operators grep for), falling back to the resolved one.
	addr := srv.Addr
	if addr == "" {
		addr = ln.Addr().String()
	}
	slog.Info("Listening", slog.String("addr", addr))

	errCh := make(chan error, 1)
	go func() { errCh <- srv.Serve(ln) }()

	select {
	case err := <-errCh:
		// Serve only returns before ctx cancellation on a real failure;
		// ErrServerClosed can't happen here because Shutdown hasn't been called.
		return fmt.Errorf("http server: %w", err)
	case <-ctx.Done():
	}

	shutdownCtx, cancel := context.WithTimeout(context.Background(), shutdownTimeout)
	defer cancel()
	if err := srv.Shutdown(shutdownCtx); err != nil {
		// Drain overran the bound; connections were cut. Not a startup-visible
		// failure — log it and exit clean, matching the pre-extraction behavior.
		slog.ErrorContext(shutdownCtx, "http shutdown", slog.Any("error", err))
	}
	if err := <-errCh; err != nil && !errors.Is(err, http.ErrServerClosed) {
		return fmt.Errorf("http server: %w", err)
	}
	return nil
}
